"use client";
import { useState } from "react";
import Link from "next/link";
import { getSupabaseBrowserClient, hasSupabaseConfig } from "../../../lib/supabase/client";
export default function LoginPage() { const [email, setEmail] = useState(""); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); async function signIn(event: React.FormEvent) { event.preventDefault(); const supabase = getSupabaseBrowserClient(); if (!supabase) return setMessage("Supabase has not been connected to this deployment yet."); setBusy(true); const { error } = await supabase.auth.signInWithOtp({ email, options: { shouldCreateUser: false, emailRedirectTo: `${window.location.origin}/auth/callback` } }); setMessage(error ? error.message : "Check your email for your secure sign-in link."); setBusy(false); } return <main className="auth-page"><section className="auth-card"><Link className="brand" href="/"><span className="brand-mark">V</span><span>VECTOR <small>GOLF PERFORMANCE</small></span></Link><p className="eyebrow">Selected-player beta</p><h1>Welcome back.</h1><p>Enter the email address your invitation was sent to. No password is required.</p><form onSubmit={signIn}><label htmlFor="email">Email address</label><input id="email" type="email" autoComplete="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="player@example.com"/><button className="primary-action" disabled={busy}>{busy ? "Sending…" : "Send secure sign-in link"}</button></form>{message && <div className="auth-message" role="status">{message}</div>}{!hasSupabaseConfig() && <small>Setup mode: add the two public Supabase environment variables before beta release.</small>}</section></main>; }
